/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. An issue that has
 * left the project (moved away) no longer appears in those rows, so the
 * project's high-water mark carries its number forward too.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const project = getDb()
    .select({ highWater: projects.issueNumberHighWater })
    .from(projects)
    .where(
      and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)),
    )
    .get();
  return Math.max(row?.value ?? 0, project?.highWater ?? 0) + 1;
}

