/**
 * Moves an issue into `projectId` under `issueNumber`, which the caller
 * allocates from the target project. The source project's high-water mark
 * keeps the number the issue leaves behind; the target's records the new one.
 */
export async function relocateIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue> {
  const db = getDb();
  const current = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  await raiseIssueNumberHighWater(orgId, current.projectId as ProjectId, current.number);

  const row = db
    .update(issues)
    .set({ projectId, number: issueNumber, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  await raiseIssueNumberHighWater(orgId, projectId, issueNumber);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

